{
  "id": "SPEC-RELEASE-INTENT-MODEL-009",
  "status": "draft",
  "owner_track": "release-security",
  "depends_on": ["SPEC-RELEASE-EXECUTION-FOUNDATION-007", "SPEC-RELEASE-DECISION-008"],
  "purpose": "Define the typed, serializable, credential-free ReleaseIntentV1 that preserves an approved ReleaseDecisionV1 across process and CI boundaries. The intent is a semantic contract, not a serialized PublishPlan and not a bag of generic fingerprints: it names exact operation identities, semantic inputs, operation prerequisites, and required artifact slots without retaining secrets or mutable prepared inputs.",
  "scope": "Layer-1 durable identity and digest types; typed semantic snapshot projections; registry/tag/forge binding identities; exact operation DAG; artifact-slot declarations; canonical encoding and fail-closed validation. Fresh graph observation, workspace locking, private prepared inputs, state/receipts, provider observation/effects, and CLI/action cutover are intentionally separate successor work.",
  "non_goals": [
    "Placing package discovery, config resolution, URL parsing, workspace access, group solving, or graph validation in callisto-model.",
    "Persisting raw registry endpoints, URL userinfo, query strings, fragments, credentials, HTTP headers, raw configuration bytes, command lines, provider stderr, arbitrary errors, local filesystem paths, or Debug-rendered values in an intent or its digest inputs.",
    "Making ReleaseIntentV1 by itself a capability to publish, tag, push, create a forge release, or reuse a stale prepared input.",
    "Using PublishPlan, PublishReport, PLAN_JSON, a cache entry, or an artifact filename as an operation identity or authorization substitute."
  ],
  "data_model": {
    "intent": "ReleaseIntentV1 is a versioned, serde-deny-unknown-fields record containing IntentDigest, DecisionDigest, source identity, typed semantic snapshot, exact operations, declared artifact slots, and schema/digest scheme versions. It is public/auditable and credential-free.",
    "semantic_snapshot": "ReleaseInputSnapshotV1 is a closed typed projection of facts that affect authorization: qualified package/version/manifest-role facts, effective release-policy facts, relevant dependency-edge facts, typed remote binding identities, source policy facts, and tag/forge policy facts. It must not expose a generic kind:String plus arbitrary fingerprint:String escape hatch.",
    "remote_binding": "RegistryBindingId is a durable identity consisting of a logical registry key and BindingDigest. The graph derives BindingDigest from a validated canonical endpoint binding only after rejecting userinfo, query, fragment, and other credential-bearing forms; the raw endpoint remains graph-private. Distinct normalized endpoint bindings must yield distinct binding identities even where their logical registry key and package/version match. Tag and forge bindings likewise identify exact target and policy, not a generic display name.",
    "operation": "ReleaseOperationId is exact and role-specific. A registry operation binds qualified package identity, target version, and RegistryBindingId; tag and forge operations bind their exact tag/target/policy identities; binary artifact attachment binds one declared ArtifactSlotId. It never delegates equality to PackageId::matches or another human-facing wildcard matcher.",
    "dag": "Every operation has an explicit, duplicate-free prerequisite set of ReleaseOperationId values. The intent stores the canonical stable topological order and rejects cycles, missing prerequisites, self-prerequisites, duplicate operation IDs, and an order inconsistent with prerequisites.",
    "artifact_slot": "ArtifactSlotV1 declares an expected binary artifact role, package/version association where applicable, platform/target identity, and intended consumer such as a forge asset. It does not contain bytes or a path. A later ArtifactManifestV1 binds actual bytes and SHA-256 to this slot, the IntentDigest, and the source commit. Source registry publishing is a separate operation and never falsely consumes a binary slot.",
    "intent_digest": "IntentDigest is SHA-256 of a versioned, length-prefixed canonical transcript of all authority-bearing typed intent fields. The encoding has explicit field ordering, semantic collection ordering, and length delimiters; it does not depend on JSON object order, skipped serde fields, TOML formatting, raw input-file bytes, platform paths, locale, wall-clock time, or Rust Debug/Ord implementation accidents."
  },
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "ReleaseIntentV1 can be constructed only from a ReleaseDecisionV1 plus explicitly typed semantic observations supplied by the graph layer. It records the exact DecisionDigest and rejects a malformed/unknown schema or an intent whose decision-derived roster, target versions, or declared operations cannot be internally reconciled. Constructing an intent from PublishPlan or a free-form JSON/TOML fingerprint does not satisfy this criterion.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "The durable snapshot uses closed typed projections for every authority-bearing input. Formatting-only changes to configuration do not change its identity, while a semantic release-policy, package/version, dependency, registry-binding, tag-policy, forge-policy, or source-policy change does. No snapshot field may be `kind: String` paired with a generic digest/fingerprint whose input set is undocumented or can include raw bytes.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "RegistryBindingId separates remote targets safely. Graph code rejects a configured endpoint containing userinfo, query, or fragment before constructing a binding. The durable model receives only logical registry identity plus BindingDigest and cannot reconstruct an endpoint. Tests prove that two distinct normalized endpoint bindings for the same logical registry, package, and version produce distinct registry operation identities, while equivalent accepted endpoint spellings produce the same binding identity.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Intent operation identity is exact and ecosystem-qualified. Two packages with the same bare name but different ecosystems cannot collide; the model rejects duplicate IDs rather than silently coalescing operations. Release-operation comparisons do not call PackageId::matches, whose documented wildcard behavior is reserved for human-facing lookup.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "The operation DAG is complete and deterministic. All prerequisites refer to operations in the same intent, each operation has one deterministic position in a stable Kahn topological order, and every prerequisite precedes its dependent. The model rejects cycles and invalid references before any future executor can act. Tie-breaking is specified by exact operation identity's canonical ordering, not enum declaration order or hash iteration.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "Intent serialization is schema-versioned and strict: unknown fields, unsupported schema/digest scheme versions, malformed digest strings, invalid qualified identities, duplicate collection keys, or an IntentDigest that does not exactly match the recomputed canonical transcript are hard validation failures before any downstream authorization. Omitted/default serialization forms have one defined canonical meaning; no field may obtain a value from process environment or current time while validating intent bytes.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "Intent and artifact-slot persistence is structurally secret-safe. A closed provenance/source enum documents every serialized intent field as Decision, TypedWorkspaceObservation, SourceTrustPolicy, StaticSchema, or ComputedCanonicalValue; no variant denotes environment, credential, raw endpoint, raw file bytes, or provider response. Schema/provenance coverage tests fail when a serialized durable field lacks exactly one provenance entry.",
      "is_error_case": true
    },
    {
      "id": "AC-008",
      "criterion": "callisto-model remains a Layer-1, provider-neutral crate. It may own typed values, parsing/validation, canonical transcript construction, SHA-256, serde, schemars, and miette-compatible error types, but it must not depend on callisto-graph, callisto-vcs, a forge SDK, URL/network clients, or a registry client. Endpoint parsing and prepared remote inputs remain above the model boundary.",
      "is_error_case": true
    }
  ],
  "verification": [
    "Golden and permutation tests cover stable canonical intent bytes/digests for reordered input vectors/maps, then mutate one semantic field at a time and assert a digest change.",
    "Negative tests cover raw/unknown fields, duplicate exact operation IDs, same bare name across ecosystems, invalid or cyclic DAGs, a stale/mismatched digest, malformed binding digest, unsafe endpoint forms at the graph-to-model boundary, and registry-binding collision attempts.",
    "Schema/provenance tests assert two-way coverage of all serialized durable fields and confirm endpoint/configuration secrets cannot enter an intent through an untyped extension field."
  ],
  "implementation_notes": [
    "Retain the existing versioned length-prefixed transcript approach rather than introduce JSON canonicalization unless independent cross-language digest recomputation becomes an explicit requirement. The format must be documented and test-vector-backed.",
    "Use BTree collections or defined sorted vectors for durable ordering. If existing enum Ord conflicts with its canonical serialized identity, implement a dedicated canonical sort key; do not rely on declaration order.",
    "Use miette for transient diagnostics and closed safe data structures for persistence. Do not persist miette reports or arbitrary provider errors.",
    "The successor graph-capability spec will construct an opaque non-Serialize/non-Clone ValidatedReleaseIntent from this durable intent, freshly re-observed workspace state, Git evidence, a workspace lock, and operation-specific private prepared inputs."
  ]
}

{
  "id": "SPEC-RELEASE-DECISION-008",
  "status": "draft",
  "owner_track": "release-security",
  "depends_on": ["SPEC-RELEASE-EXECUTION-FOUNDATION-007"],
  "purpose": "Make the release roster and its version/lane choices an explicit, deterministic graph decision. The decision is the only upstream authority for which packages participate in a durable release; later intent, validation, and execution layers must consume it rather than reconstructing a roster from PublishPlan or mutable configuration.",
  "scope": "Graph-owned release selection, linked-group closure, group/cascade/prerelease policy evaluation, target-version assignment, deterministic explanations, and the safe serializable decision record consumed by the intent-model spec. This spec is policy output only: it neither authorizes effects nor defines provider endpoints, artifact bytes, workspace locks, or recovery.",
  "non_goals": [
    "Changing the meaning of existing user configuration for linked groups, fixed groups, prerelease mode, or dependency cascades without a separately accepted compatibility specification.",
    "Treating a package's bare name as release-operation identity. All durable decision entries use an ecosystem-qualified package identity.",
    "Selecting extra unrelated packages merely because they share a version, a registry, or a human-readable name with a selected package.",
    "Publishing, tagging, building artifacts, or reading credentials."
  ],
  "data_model": {
    "release_decision": "ReleaseDecisionV1 is a versioned, serializable, credential-free graph result. It records the explicit selection request, the resolved effective policy, the final roster, each final target version, and machine-readable inclusion reasons.",
    "roster_entry": "Each roster entry identifies one ReleasePackageId, its resolved current and target versions when known, and a non-empty ordered set of closed inclusion reasons: ExplicitSelection, LinkedGroup { group_id }, FixedGroup { group_id }, Cascade { from, edge_kind }, or PreReleasePolicy { policy_id }. Free-form explanatory text is diagnostic-only and is not a durable authority field.",
    "policy_snapshot": "The decision records typed semantic policy values that actually affected roster membership or target versions. It does not contain raw callisto.toml bytes, arbitrary configuration fragments, registry URLs, environment values, or path-independent debug strings.",
    "decision_digest": "DecisionDigest is computed from a versioned, length-prefixed canonical transcript of the typed decision fields. Map/set-like values and roster entries have one specified deterministic order; a decision digest never depends on serde field omission, Debug output, source formatting, or wall-clock time."
  },
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "The graph derives ReleaseDecisionV1 from an explicit selection plus freshly resolved workspace configuration and discovered package graph. No executor, provider adapter, CLI handoff, or downstream intent constructor may call plan_publish, inspect PublishPlan, or re-run selection rules to discover additional members. An empty explicit selection is rejected unless an existing, documented configuration mode supplies an explicit all-packages selection; it is never silently interpreted as all packages.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "Selecting any member of a linked group includes every package in that linked group. If linked groups overlap, closure is transitive: all packages reachable through linked-group membership are included exactly once. A package outside that closure is included only by an explicit selection or by an already configured fixed-group, dependency-cascade, or prerelease rule that names the causal package/policy in its inclusion reason. The implementation must not use an unsatisfiable rule such as rejecting a package merely because more than one package qualifies.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "Prerelease behavior is configuration-driven. The decision applies the existing configured prerelease/lane policy after linked-group closure and records exactly which roster entries it affected and why. A workspace-wide prerelease setting may shape target versions only for packages that are in the approved final roster; it cannot cause an off-roster package to be tagged, published, or treated as a release operation. A test covers a configured prerelease workspace with an otherwise qualifying off-roster package.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Every final roster entry has exactly one resolved target-version outcome before a decision is emitted. Conflicting fixed-group, linked-group, cascade, or prerelease constraints are rejected with a structured diagnostic naming the qualified packages, relevant group or policy identifiers, and incompatible outcomes. Absence of a failure is not treated as a valid version decision.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "ReleaseDecisionV1 is deterministic: equivalent fresh workspace state and explicit selection produce byte-identical canonical decision data and the same DecisionDigest across process runs. Ordering is by defined semantic keys, including ecosystem-qualified package identity; Rust declaration order, HashMap iteration, filesystem enumeration order, and DepKind's declaration order are not valid ordering definitions. Dependency/cascade explanations are ordered by their defined exact identity.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "The decision exposes an inspectable explanation for every included and rejected requested package without leaking credentials or raw endpoint/configuration text. User-facing errors use miette diagnostics with stable codes and remediation; the durable decision itself retains only closed reason variants and safe typed identifiers, not rendered diagnostics.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "The decision is a graph-layer product. callisto-model provides only dependency-free identity/version primitives and canonical digest primitives; it must not depend on callisto-graph for package discovery, configuration resolution, group membership, or dependency solving. The model/graph licensing boundary remains intact.",
      "is_error_case": true
    }
  ],
  "verification": [
    "Table-driven tests cover isolated selection, linked-group closure, overlapping linked groups, fixed-group interaction, cascade interaction, configured prerelease with an off-roster package, and conflicting target-version outcomes.",
    "Permutation tests vary package discovery and dependency input order and assert equal decision bytes/digests and stable inclusion-reason order.",
    "Tests demonstrate that same bare package names in different ecosystems remain distinct decision entries."
  ],
  "implementation_notes": [
    "Reuse the existing group, cascade, prerelease, PackageId, Version, and graph structures where their semantics match; introduce a new typed result rather than extending PublishPlan into authority.",
    "Use BTreeMap/BTreeSet or explicitly sorted Vec values at durable boundaries. Do not add Rayon or Tokio: deriving one release decision is policy-sensitive and its deterministic evidence matters more than parallel traversal.",
    "The next spec, SPEC-RELEASE-INTENT-MODEL-009, consumes this result. Git trust, locks, prepared effect inputs, and actual effect dispatch are later dependent specs."
  ]
}
